 static TableLayoutPanel Grid(int cols,int rows){return new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=cols,RowCount=rows,Margin=Padding.Empty};}
 static void Rows(TableLayoutPanel p,params int[] heights){foreach(int h in heights)p.RowStyles.Add(h<0?new RowStyle(SizeType.Percent,100):new RowStyle(SizeType.Absolute,h));}
 static Label LabelText(string text,float size,Color color){return new Label{Text=text,Font=new Font("Consolas",size),ForeColor=color,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true,Margin=Padding.Empty};}
